#include <memory>
#include <iostream>

template <typename T, typename D>
bool operator<(std::nullptr_t, const std::unique_ptr<T, D>& y) {
    return y == nullptr;
}

int main() {
    std::unique_ptr<int> ptr = nullptr;
    if (nullptr < ptr) {
        std::cout << "nullptr is less than unique_ptr" << std::endl;
    }
    return 0;
}
